#!/usr/bin/env node
/**
 * Generates src/environments/environment.ts from environment variables.
 *
 * Used by GitHub Actions (Secrets/Variables) and local dev (.env file).
 * The generated file is gitignored — never commit credentials.
 */
const fs = require('node:fs');
const path = require('node:path');

const rootDir = path.join(__dirname, '..');
const envFilePath = path.join(rootDir, '.env');
const outputPath = path.join(rootDir, 'src/environments/environment.ts');

function loadDotEnv(filePath) {
  if (!fs.existsSync(filePath)) {
    return;
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  for (const line of contents.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (!(key in process.env)) {
      process.env[key] = value;
    }
  }
}

function escapeString(value) {
  return value.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

loadDotEnv(envFilePath);

const production =
  process.env.ENVIRONMENT === 'production' || process.env.NODE_ENV === 'production';

const environment = {
  production,
  spotify: {
    clientId: process.env.SPOTIFY_CLIENT_ID ?? '',
    redirectUri: process.env.SPOTIFY_REDIRECT_URI ?? 'http://127.0.0.1:4200',
  },
  googleMusicApi: {
    baseUrl: process.env.GOOGLE_MUSIC_API_BASE_URL ?? 'http://localhost:5000/api',
  },
};

const fileContents = `/** Generated by scripts/generate-environment.js — do not edit or commit. */
export const environment = {
  production: ${environment.production},
  spotify: {
    clientId: '${escapeString(environment.spotify.clientId)}',
    redirectUri: '${escapeString(environment.spotify.redirectUri)}',
  },
  googleMusicApi: {
    baseUrl: '${escapeString(environment.googleMusicApi.baseUrl)}',
  },
};
`;

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, fileContents, 'utf8');

console.log(`Generated ${path.relative(rootDir, outputPath)} (production=${production})`);
if (!environment.spotify.clientId) {
  console.warn('Warning: SPOTIFY_CLIENT_ID is not set. Spotify login will not work until configured.');
}
